  # "Every check of section 10.4 (entries, totals, reservations, projection, audit rows, operation receipts, idempotency receipts, id sequence, money) is run and reported per company_id"
  # "A clean run emits no difference event."
  it "passes a clean two-company run with every check reported per company and no difference event" do
    t0 = Time.utc(2026, 1, 5, 9)
    op_id = "11111111-1111-1111-1111-111111111111"
    entry = lambda do |company_id, **o|
      {
        "id" => 1, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
