        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => t0, "updated_at" => t0
      }.merge(o.transform_keys(&:to_s))
    end
    reservation = lambda do |company_id, **o|
      { "company_id" => company_id, "entry_id" => 1, "invoice_id" => 1, "state" => "committed",
        "disposition" => "active", "operation_id" => op_id, "created_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
        .merge(o.transform_keys(&:to_s))
    end
    operation = lambda do |company_id, **o|
      { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "state" => "committed",
        "desired_entry_ids" => [1], "disposition" => "active", "generation" => 1, "created_at" => t0,
        "finished_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("invoice_operations").index_with { nil })
        .merge(o.transform_keys(&:to_s))
    end
    intent = lambda do |company_id, **o|
      { "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "generation" => 1,
        "state" => "committed", "created_at" => t0, "finished_at" => t0 }.merge(o.transform_keys(&:to_s))
    end
    projection_row = lambda do |company_id, **o|
      entry.call(company_id, **o).merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch("unbilled"),
        "review_status" => TimesheetEntry.review_statuses.fetch("not_required")
      )
    end
    checkpoint_of = lambda do |entries:, reservations:, operations:|
      tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
      Timekeeping::Handoff::Checkpoint.build(
        tables: tables.merge("entries" => entries, "reservations" => reservations, "invoice_operations" => operations)
      )
    end
    snapshot = ->(company_id) { { company_id: company_id, values: { [:invoice, 1, :discount] => BigDecimal("5") } } }
    companies = [101, 202]
    rows = -> { { entries: companies.map { entry.call(_1) }, reservations: companies.map { reservation.call(_1) },
                  operations: companies.map { operation.call(_1) } } }
    inputs = {
      source: checkpoint_of.call(**rows.call), checkpoint: checkpoint_of.call(**rows.call),
      projection: companies.map { projection_row.call(_1) },
      source_intents: companies.map { intent.call(_1) }, intents: companies.map { intent.call(_1) },
      next_entry_id: 2,
      money_before: companies.index_with { snapshot.call(_1) }, money_after: companies.index_with { snapshot.call(_1) }
    }

    result = described_class.run(**inputs)

    expect(result.abort?).to be(false)
    expect(result.unassigned).to eq([])
    expect(result.companies.keys).to contain_exactly(101, 202)
    result.companies.each do |company_id, report|
      expect(report.company_id).to eq(company_id)
      expect(report.abort?).to be(false)
      expect(report.checks.size).to be >= 9
      expect(report.checks.values).to all(eq([]))
      expect(report.unlisted).to eq([])
    end
    expect(result.companies[101].checks.keys).to match_array(result.companies[202].checks.keys)

    assert_no_event_reported("Timekeeping::ReconciliationDifferenceFound") do
      assert_no_event_reported("Timekeeping::FinancialSnapshotChanged") do
        described_class.report(result)
      end
    end
  end
end

