RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "A difference is "listed" only when that list has it for the same `company_id` and the same row. A correction listed for one company never explains a difference in another."
  # "Any difference that the pre-flight did not list aborts the handoff."
  it "lets a listed correction pass only for its own company, row and field" do
    t0 = Time.utc(2026, 1, 5, 9)
    op_id = "11111111-1111-1111-1111-111111111111"
    entry = lambda do |company_id, **o|
      {
        "id" => 1, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => t0, "updated_at" => t0
      }.merge(o.transform_keys(&:to_s))
    end
    reservation = lambda do |company_id|
      { "company_id" => company_id, "entry_id" => 1, "invoice_id" => 1, "state" => "committed",
        "disposition" => "active", "operation_id" => op_id, "created_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
    end
    operation = lambda do |company_id|
      { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "state" => "committed",
        "desired_entry_ids" => [1], "disposition" => "active", "generation" => 1, "created_at" => t0, "finished_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("invoice_operations").index_with { nil })
    end
    intent = lambda do |company_id|
      { "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "generation" => 1,
        "state" => "committed", "created_at" => t0, "finished_at" => t0 }
    end
    projection_row = lambda do |company_id, **o|
      entry.call(company_id, **o).merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch("unbilled"),
        "review_status" => TimesheetEntry.review_statuses.fetch("not_required")
      )
    end
    checkpoint_of = lambda do
      tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
      Timekeeping::Handoff::Checkpoint.build(
        tables: tables.merge("entries" => [entry.call(101), entry.call(202)],
                             "reservations" => [reservation.call(101), reservation.call(202)],
                             "invoice_operations" => [operation.call(101), operation.call(202)])
      )
    end
    snapshot = ->(company_id) { { company_id: company_id, values: { [:invoice, 1, :discount] => BigDecimal("5") } } }
    run_with = lambda do |projection, corrections|
      described_class.run(
        source: checkpoint_of.call, checkpoint: checkpoint_of.call, projection: projection,
        source_intents: [intent.call(101), intent.call(202)], intents: [intent.call(101), intent.call(202)],
        next_entry_id: 2,
        money_before: { 101 => snapshot.call(101), 202 => snapshot.call(202) },
        money_after: { 101 => snapshot.call(101), 202 => snapshot.call(202) },
        listed_corrections: corrections
      )
    end

    # Both companies' projection rows lag on locked, as a first-cutover correction does before the flip.
    lagging = [projection_row.call(101, locked: false), projection_row.call(202, locked: false)]
    unlisted = run_with.call(lagging, {})
    locked_difference = unlisted.companies.fetch(101).unlisted.find { |difference| difference.field.to_s == "locked" }
    expect(locked_difference).not_to be_nil
    correction = described_class::Correction.new(check: locked_difference.check, row_key: locked_difference.row_key, field: "locked")

    listed_for_a = run_with.call(lagging, { 101 => [correction] })
    expect(listed_for_a.companies.fetch(101).abort?).to be(false)
    expect(listed_for_a.companies.fetch(101).listed.map { |difference| difference.field.to_s }).to include("locked")
    expect(listed_for_a.companies.fetch(202).abort?).to be(true)
    expect(listed_for_a.companies.fetch(202).unlisted.map { |difference| difference.field.to_s }).to include("locked")
    expect(listed_for_a.abort?).to be(true)

    # The locked correction must not explain another changed field on the same row.
    with_duration_change = [projection_row.call(101, locked: false, duration: 61.0), projection_row.call(202)]
    mixed = run_with.call(with_duration_change, { 101 => [correction] })
    expect(mixed.companies.fetch(101).abort?).to be(true)
    expect(mixed.companies.fetch(101).unlisted.map { |difference| difference.field.to_s }).to include("duration")
    expect(mixed.companies.fetch(101).unlisted.map { |difference| difference.field.to_s }).not_to include("locked")
  end
end

