    snapshot = lambda do |company_id, discount|
      { company_id: company_id, values: { [:invoice, 1, :amount] => BigDecimal("100"), [:invoice, 1, :discount] => discount } }
    end
    run_with = lambda do |money_before, money_after|
      described_class.run(
        source: checkpoint_of.call, checkpoint: checkpoint_of.call,
        projection: [projection_row.call(101), projection_row.call(202)],
        source_intents: [intent.call(101), intent.call(202)], intents: [intent.call(101), intent.call(202)],
        next_entry_id: 2, money_before: money_before, money_after: money_after
      )
    end

    changed = run_with.call(
      { 101 => snapshot.call(101, BigDecimal("5")), 202 => snapshot.call(202, BigDecimal("5")) },
      { 101 => snapshot.call(101, BigDecimal("15")), 202 => snapshot.call(202, BigDecimal("5")) }
