    expect(changed.companies.fetch(202).abort?).to be(false)
    expect(changed.companies.fetch(202).checks.values.flatten).to eq([])

    # Company 202 has entries but neither snapshot: its money check must not pass unchecked.
    missing = run_with.call({ 101 => snapshot.call(101, BigDecimal("5")) }, { 101 => snapshot.call(101, BigDecimal("5")) })
    expect(missing.companies.fetch(101).abort?).to be(false)
    expect(missing.companies.fetch(202).abort?).to be(true)
    expect(missing.companies.fetch(202).unlisted.map(&:reason)).to include(:snapshot_missing)
    expect(missing.companies.fetch(202).unlisted.map(&:company_id).uniq).to eq([202])
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "One failing case per check (a changed field, a float differing in its last bit, a `provisional` reservation, a `prepared` operation, a `pending` intent, a lower sequence, a changed invoice discount), each reported under the right `company_id` and aborting."
  # "Sequence is higher": an equal value is not higher, so it fails too.
  it "aborts under the right company for a provisional reservation, a prepared operation, a pending intent and a sequence not higher" do
    t0 = Time.utc(2026, 1, 5, 9)
    op_id = "11111111-1111-1111-1111-111111111111"
    entry = lambda do |company_id, id|
      {
        "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => t0, "updated_at" => t0
      }
    end
    ids = { 101 => 1, 202 => 5 }
    reservation = lambda do |company_id, state = "committed"|
      { "company_id" => company_id, "entry_id" => ids[company_id], "invoice_id" => 1, "state" => state,
        "disposition" => "active", "operation_id" => op_id, "created_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
    end
    operation = lambda do |company_id, state = "committed"|
      { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "state" => state,
        "desired_entry_ids" => [ids[company_id]], "disposition" => "active", "generation" => 1, "created_at" => t0,
        "finished_at" => state == "committed" ? t0 : nil }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("invoice_operations").index_with { nil })
    end
    intent = lambda do |company_id, state = "committed"|
      { "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "generation" => 1,
        "state" => state, "created_at" => t0, "finished_at" => state == "pending" ? nil : t0 }
    end
    projection_row = lambda do |company_id|
      entry.call(company_id, ids[company_id]).merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch("unbilled"),
        "review_status" => TimesheetEntry.review_statuses.fetch("not_required")
      )
    end
    snapshot = ->(company_id) { { company_id: company_id, values: { [:invoice, 1, :discount] => BigDecimal("5") } } }
    run_case = lambda do |reservations: [reservation.call(101), reservation.call(202)],
                          operations: [operation.call(101), operation.call(202)],
                          intents: [intent.call(101), intent.call(202)], next_entry_id: 6|
      checkpoint_of = lambda do
        tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
        Timekeeping::Handoff::Checkpoint.build(
          tables: tables.merge("entries" => [entry.call(101, 1), entry.call(202, 5)],
                               "reservations" => reservations, "invoice_operations" => operations)
        )
      end
      described_class.run(
        source: checkpoint_of.call, checkpoint: checkpoint_of.call,
        projection: [projection_row.call(101), projection_row.call(202)],
        source_intents: intents, intents: intents, next_entry_id: next_entry_id,
        money_before: { 101 => snapshot.call(101), 202 => snapshot.call(202) },
        money_after: { 101 => snapshot.call(101), 202 => snapshot.call(202) }
      )
    end

    cases = {
      provisional_remains: run_case.call(reservations: [reservation.call(101, "provisional"), reservation.call(202)]),
      operation_prepared: run_case.call(operations: [operation.call(101, "prepared"), operation.call(202)]),
      intent_pending: run_case.call(intents: [intent.call(101, "pending"), intent.call(202)])
    }
    cases.each do |reason, result|
      expect(result.abort?).to be(true), "#{reason} should abort"
      expect(result.companies.fetch(101).abort?).to be(true)
      expect(result.companies.fetch(101).unlisted.map(&:reason)).to include(reason)
      expect(result.companies.fetch(202).abort?).to be(false), "#{reason} leaked into company 202"
      expect(result.companies.fetch(202).checks.values.flatten).to eq([])
    end

    # Company 202's highest checkpoint entry id is 5; company 101's is 1.
    [5, 4].each do |next_entry_id|
      result = run_case.call(next_entry_id: next_entry_id)
      expect(result.abort?).to be(true)
      expect(result.companies.fetch(202).unlisted.map(&:reason)).to include(:sequence_not_higher)
      expect(result.companies.fetch(101).abort?).to be(false)
    end
  end
end

