    reservation = lambda do |company_id|
      { "company_id" => company_id, "entry_id" => 1, "invoice_id" => 1, "state" => "committed",
        "disposition" => "active", "operation_id" => op_id, "created_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
    end
    operation = lambda do |company_id|
      { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "state" => "committed",
        "desired_entry_ids" => [1], "disposition" => "active", "generation" => 1, "created_at" => t0, "finished_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("invoice_operations").index_with { nil })
    end
    intent = lambda do |company_id|
      { "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "generation" => 1,
        "state" => "committed", "created_at" => t0, "finished_at" => t0 }
    end
    checkpoint_of = lambda do |note|
      tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
      Timekeeping::Handoff::Checkpoint.build(
        tables: tables.merge("entries" => [entry.call(101, note), entry.call(202, "same")],
                             "reservations" => [reservation.call(101), reservation.call(202)],
                             "invoice_operations" => [operation.call(101), operation.call(202)])
      )
    end
    projection = [101, 202].map do |company_id|
      entry.call(company_id, company_id == 101 ? "changed" : "same").merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch("unbilled"),
        "review_status" => TimesheetEntry.review_statuses.fetch("not_required"),
        "locked" => false
      )
    end
    intents = [intent.call(101), intent.call(202)]
    money = ->(discount) { { 101 => { company_id: 101, values: { [:invoice, 1, :discount] => discount } } } }
    source = checkpoint_of.call("original")
    checkpoint = checkpoint_of.call("changed")
    inputs = {
      source: source, checkpoint: checkpoint, projection: projection, source_intents: intents, intents: intents,
      next_entry_id: 2, money_before: money.call(BigDecimal("5")), money_after: money.call(BigDecimal("15"))
    }
    copies = Marshal.load(Marshal.dump(inputs.except(:source, :checkpoint)))
    source_rows = Marshal.load(Marshal.dump(source.rows))
    checkpoint_rows = Marshal.load(Marshal.dump(checkpoint.rows))

    writes = []
    subscriber = ActiveSupport::Notifications.subscribe("sql.active_record") do |*, payload|
      writes << payload[:sql] if payload[:sql].match?(/\A\s*(INSERT|UPDATE|DELETE)\b/i)
    end
    begin
      result = described_class.run(**inputs)
    ensure
      ActiveSupport::Notifications.unsubscribe(subscriber)
    end

    expect(result.abort?).to be(true)
    expect(writes).to eq([])
    expect(inputs.except(:source, :checkpoint)).to eq(copies)
    expect(source.rows).to eq(source_rows)
    expect(checkpoint.rows).to eq(checkpoint_rows)
    expect(projection.first["locked"]).to be(false)
    expect(projection.first["bill_status"]).to eq(TimesheetEntry.bill_statuses.fetch("unbilled"))
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Emit every reconciliation difference and any financial snapshot change with `company_id`."
  # Event history is readable across every workspace, so the payloads must hold identifiers, not row or money values.
  it "emits one difference event per difference with its company id and a financial event for the changed discount" do
    t0 = Time.utc(2026, 1, 5, 9)
    op_id = "11111111-1111-1111-1111-111111111111"
    entry = lambda do |company_id, note|
      {
        "id" => 1, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => note, "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => t0, "updated_at" => t0
      }
    end
    reservation = lambda do |company_id|
      { "company_id" => company_id, "entry_id" => 1, "invoice_id" => 1, "state" => "committed",
        "disposition" => "active", "operation_id" => op_id, "created_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
    end
    operation = lambda do |company_id|
      { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "state" => "committed",
        "desired_entry_ids" => [1], "disposition" => "active", "generation" => 1, "created_at" => t0, "finished_at" => t0 }
        .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("invoice_operations").index_with { nil })
    end
    intent = lambda do |company_id|
      { "company_id" => company_id, "invoice_id" => 1, "operation_id" => op_id, "generation" => 1,
        "state" => "committed", "created_at" => t0, "finished_at" => t0 }
    end
    checkpoint_of = lambda do |note_b|
      tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
      Timekeeping::Handoff::Checkpoint.build(
        tables: tables.merge("entries" => [entry.call(101, "kept"), entry.call(202, note_b)],
                             "reservations" => [reservation.call(101), reservation.call(202)],
                             "invoice_operations" => [operation.call(101), operation.call(202)])
      )
    end
    projection = [[101, "kept"], [202, "secret-note-xyz"]].map do |company_id, note|
      entry.call(company_id, note).merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch("unbilled"),
        "review_status" => TimesheetEntry.review_statuses.fetch("not_required")
      )
    end
    snapshot = lambda do |company_id, discount|
      { company_id: company_id, values: { [:invoice, 9, :discount] => discount } }
    end
    intents = [intent.call(101), intent.call(202)]
    result = described_class.run(
      source: checkpoint_of.call("original"), checkpoint: checkpoint_of.call("secret-note-xyz"),
      projection: projection, source_intents: intents, intents: intents, next_entry_id: 2,
      money_before: { 101 => snapshot.call(101, BigDecimal("5")), 202 => snapshot.call(202, BigDecimal("5")) },
      money_after: { 101 => snapshot.call(101, BigDecimal("987654.32")), 202 => snapshot.call(202, BigDecimal("5")) }
    )
    differences = result.companies.values.flat_map { |report| report.checks.values.flatten }
    expect(differences.map(&:company_id).uniq).to contain_exactly(101, 202)

    reconciliation_events = RailsEventViewer::Entry.where(name: "Timekeeping::ReconciliationDifferenceFound")
    financial_events = RailsEventViewer::Entry.where(name: "Timekeeping::FinancialSnapshotChanged")
    returned = nil
    expect { returned = described_class.report(result) }
      .to change { reconciliation_events.count }.by(differences.size)
      .and change { financial_events.count }.by(1)
    expect(returned).to eq(result)

    stored = reconciliation_events.order(:id).last(differences.size).map { |row| row.payload["data"] }
    stored.each { |data| expect(data.keys).to include("company_id") }
    expect(stored.pluck("company_id")).to match_array(differences.map(&:company_id))
    expect(JSON.generate(stored)).not_to include("secret-note-xyz")
    expect(JSON.generate(stored)).not_to include("987654")

    money_data = financial_events.order(:id).last.payload["data"]
    expect(money_data.keys).to match_array(%w[company_id kind record_id field])
    expect(money_data["company_id"]).to eq(101)
    expect(money_data["record_id"]).to eq(9)
    expect(money_data["field"].to_s).to eq("discount")
    expect(JSON.generate(money_data)).not_to include("987654")
  end
end
